from panda_backtest.api.api import *
import panda_data
import numpy as np

UNDERLYING_LIST = ["AU", "AG", "CU", "RB", "M", "TA"]


def initialize(context):
    context.trade_account = "0000"
    context.channel_n = 20
    context.close_hist = {}


def before_trading(context):
    today = str(context.now)
    df = panda_data.get_future_dominant(
        underlying_symbol=UNDERLYING_LIST,
        start_date=today,
        end_date=today,
    )
    if df is None or df.empty:
        return
    for _, row in df.iterrows():
        context.close_hist.setdefault(row["symbol"], [])


def handle_data(context, data):
    for symbol, hist in context.close_hist.items():
        try:
            bar = data[symbol]
        except Exception:
            continue
        hist.append(float(bar.close))
        if len(hist) < context.channel_n + 1:
            continue
        highest = max(hist[-(context.channel_n + 1):-1])
        lowest = min(hist[-(context.channel_n + 1):-1])
        if bar.close > highest:
            buy_open(context.trade_account, symbol, 1, style=MarketOrderStyle)
        elif bar.close < lowest:
            sell_open(context.trade_account, symbol, 1, style=MarketOrderStyle)

